-- [D] META 현재값 — API_URL 이 standalone 이면 전환 전, PKG.멤버 면 전환 완료
SELECT API_ID, API_URL FROM SCM_ADM_API_M WHERE API_ID IN ('DMF0082_futurePriceInfo_IF') ORDER BY API_ID;
SELECT UPPER(PROC_NM) PROC_NM, COUNT(*) CNT FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) IN ('PR_SCM_MST_EXCHANGE_RATE_UI', 'PR_DM_PLN_CFM_TO_MKT_FCST', 'PR_SCM_MST_EXCHANGE_RATE') OR PROC_NM IN ('PKG_DMF0082.P_PR_SCM_MST_EXCHANGE_RATE_UI', 'PKG_DMF0082.P_PR_DM_PLN_CFM_TO_MKT_FCST', 'PKG_DMF0082.P_PR_SCM_MST_EXCHANGE_RATE') GROUP BY UPPER(PROC_NM) ORDER BY 1;

-- [E] 앱계정
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0082';
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER = 'SCMP_APP' AND SYNONYM_NAME = 'PKG_DMF0082';
